        r=subprocess.run([name,'--version'],text=True,capture_output=True,timeout=60)
        return {'status':r.returncode,'stdout':r.stdout,'stderr':r.stderr,'error':None,'elapsed_ms':round((time.monotonic()-started)*1000)}
    except FileNotFoundError:
        return {'status':None,'stdout':'','stderr':'','error':'ENOENT','elapsed_ms':round((time.monotonic()-started)*1000)}
    except subprocess.TimeoutExpired:
        return {'status':None,'stdout':'','stderr':'','error':'ETIMEDOUT','elapsed_ms':round((time.monotonic()-started)*1000)}

def snapshot():
    return {'marker':MARKER,'runtime':'python','version':platform.python_version(),'requested_python':os.environ.get('PYTHON_VERSION'),'requested_poetry':os.environ.get('POETRY_VERSION'),'app_imports_poetry':importlib.util.find_spec('poetry') is not None,'tools':{name:tool(name) for name in ('node','npm','yarn','pnpm','python','pip','poetry')}}

if '--build' in sys.argv:
    value=snapshot()
    Path('qa341-built.json').write_text(json.dumps(value,ensure_ascii=False))
    print(json.dumps(value,ensure_ascii=False),flush=True)
else:
    from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
    built=json.loads(Path('/opt/render/project/src/qa341-built.json').read_text())
    value=snapshot();value['built']=built;body=json.dumps(value,ensure_ascii=False).encode()
    class Handler(BaseHTTPRequestHandler):
        def log_message(self,*args):pass
        def do_GET(self):
            self.send_response(200);self.send_header('Content-Type','application/json');self.send_header('Content-Length',str(len(body)));self.end_headers();self.wfile.write(body)
    ThreadingHTTPServer(('0.0.0.0',int(os.environ.get('PORT','3000'))),Handler).serve_forever()

